"""Ticket records."""


class Ticket:
    def __init__(self, team, hours):
        self.team = team
        self.hours = hours

    def __repr__(self):
        return "Ticket(%r, %r)" % (self.team, self.hours)


ROWS = [('web', 9), ('data', 49), ('web', 34), ('web', 26), ('data', 8), ('ops', 59)]


def load_tickets():
    """Yield the stored tickets one at a time."""
    for team, hours in ROWS:
        yield Ticket(team, hours)

