"""Billing for tickets. Rate lookups are billed, so the charge is remembered."""
import rates


class TicketBill:
    def __init__(self):
        self._tickets = []
        self._charge = None

    def add(self, ticket):
        """Add one ticket to the bill."""
        self._tickets.append(ticket)

    def charge(self):
        """Return the total charge: hours times the rate for each ticket's team.

        The result is remembered: asking again without adding anything makes no new rate lookups.
        """
        if self._charge is None:
            self._charge = sum(x.hours * rates.rate_for(x.team) for x in self._tickets)
        return self._charge

